import { commissionDetailApi, extractlistApi } from '@/api/finance';
import { mapState } from 'vuex';
export default {
    name: 'commissionDetails',
    data () {
        return {
            modals: false,
            spinShow: false,
            detailsData: {},
            Ids: 0,
            loading: false,
            formValidate: {
                nickname: '',
                start_time: '',
                end_time: '',
                page: 1, // 当前页
                limit: 20 // 每页显示条数
            },
            total: 0,
            columns: [
                // {
                //     title: '昵称',
                //     key: 'nickname'
                // },
                {
                    title: '佣金金额',
                    key: 'number',
                    minWidth:80
                },
                {
                    title: '获得时间',
                    key: '_add_time',
                    minWidth:150
                },
                {
                    title: '备注',
                    key: 'mark',
                    minWidth:330
                }
            ],
            tabList: []

        }
    },
    computed: {
        ...mapState('admin/layout', [
            'isMobile'
        ]),
        labelWidth () {
            return this.isMobile ? undefined : 80;
        },
        labelPosition () {
            return this.isMobile ? 'top' : 'left';
        }
    },
    mounted () {
        if (this.Ids) {
            this.getList();
        }
    },
    methods: {
        // 时间
        onchangeTime (e) {
            this.formValidate.start_time = e[0];
            this.formValidate.end_time = e[1];
        },
        // 详情
        getDetails (id) {
            this.Ids = id;
            this.spinShow = true;
            commissionDetailApi(id).then(async res => {
                if (res.status === 200) {
                    let data = res.data
                    this.detailsData = data.user_info;
                    this.spinShow = false;
                } else {
                    this.spinShow = false;
                    this.$Message.error(res.msg);
                }
            }).catch(res => {
                this.spinShow = false;
                this.$Message.error(res.msg);
            })
        },
        // 列表
        getList () {
            this.loading = true;
            extractlistApi(this.Ids, this.formValidate).then(async res => {
                let data = res.data;
                this.tabList = data.data;
                this.total = data.count;
                this.loading = false;
            }).catch(res => {
                this.loading = false;
                this.$Message.error(res.msg);
            })
        },
        pageChange (index) {
            this.formValidate.page = index
            this.getList();
        },
        // 搜索
        userSearchs () {
            this.formValidate.page = 1;
            this.getList();
        }
    }
}
